import 'dart:convert';

import 'package:flutter/services.dart';

import '../../core/chat/content_block.dart';
import '../../core/chat/message.dart';
import '../../core/on_device/on_device_capability.dart';
import '../../core/providers/providers.dart';
import '../../core/util/json.dart';
import '../on_device/system_model_mapping.dart';
import '../on_device/system_on_device.dart';

/// Apple Intelligence: replies from Foundation Models and images from Image
/// Playground, both generated by the system on this device.
class AppleIntelligenceOnDevice extends SystemOnDevice {
  AppleIntelligenceOnDevice({MethodChannel? methods, EventChannel? events})
    : super(
        methods:
            methods ??
            const MethodChannel('tw.avianjay.tako/apple_intelligence'),
        events:
            events ??
            const EventChannel('tw.avianjay.tako/apple_intelligence/events'),
        models: const [appleModel, appleImageModel],
      );

  @override
  String get service => 'apple';

  @override
  Set<String> get setupFailures => const {
    'apple_unavailable',
    'apple_update',
    'apple_disabled',
    'apple_not_ready',
    'apple_failed',
  };

  @override
  LocalModel describe(String id, Map<Object?, Object?> details) {
    if (id == appleImageModel.id) return appleImageModel;
    return LocalModel.system(
      id: id,
      name: appleModel.displayName,
      profile: ModelProfile(
        id: id,
        autoDetect: true,
        capabilities: ProviderCapabilities(
          tools: details['tools'] == true,
          contextWindow: (asInt(details['contextWindow']) ?? 4096).clamp(
            1,
            1 << 20,
          ),
        ),
        maxOutputTokens: 1024,
      ),
    );
  }

  @override
  Map<String, Object?> requestFields(
    ProviderConfig config,
    ChatRequest request,
  ) {
    if (config.model == appleImageModel.id) return _imageFields(request);
    return {
      // The model follows instructions over the prompt, so the system prompt,
      // tool definitions and reply format stay out of the untrusted transcript.
      'instructions': [
        request.systemPrompt,
        if (request.tools.isNotEmpty)
          'Tools: ${jsonEncode(systemModelTools(request))}',
        systemModelInstruction(request),
      ].where((part) => part.isNotEmpty).join('\n\n'),
      'prompt': jsonEncode({'conversation': systemModelConversation(request)}),
      'useTools': request.tools.isNotEmpty,
      'tools': [for (final tool in request.tools) tool.name],
      'maxOutputTokens': request.maxTokens ?? config.maxOutputTokens,
    };
  }

  /// The newest user prompt and its reference image, as Image Playground
  /// concepts. Earlier turns are not part of an image request.
  Map<String, Object?> _imageFields(ChatRequest request) {
    final message = request.messages.reversed
        .where((message) => message.role == MessageRole.user)
        .firstOrNull;
    final prompt =
        message?.content
            .whereType<TextBlock>()
            .map((block) => block.text)
            .join('\n')
            .trim() ??
        '';
    final references = message?.content.whereType<ImageBlock>().toList() ?? [];
    if (prompt.isEmpty) {
      throw const ProviderError(
        'Enter an image prompt',
        code: 'invalid_request',
      );
    }
    if (references.length > 1) {
      throw const ProviderError(
        'Image Playground uses at most one reference image',
        code: 'apple_image_input',
      );
    }
    const unreadable = ProviderError(
      'Reference image could not be loaded',
      code: 'invalid_image',
    );
    if (references.any((reference) => reference.data == null)) {
      throw unreadable;
    }
    try {
      return {
        'prompt': prompt,
        'images': [
          for (final reference in references) base64Decode(reference.data!),
        ],
      };
    } on FormatException {
      throw unreadable;
    }
  }
}
